function formatarMoeda(valor) {
  const numero = Number(valor) || 0;
  const negativo = numero < 0;
  const fixo = Math.abs(numero).toFixed(2);
  const partes = fixo.split(".");
  let inteiro = partes[0];
  const centavos = partes[1];
  let comSeparador = "";
  let contador = 0;
  for (let i = inteiro.length - 1; i >= 0; i--) {
    comSeparador = inteiro.charAt(i) + comSeparador;
    contador++;
    if (contador % 3 === 0 && i !== 0) {
      comSeparador = "." + comSeparador;
    }
  }
  return (negativo ? "-R$ " : "R$ ") + comSeparador + "," + centavos;
}

function formatarMoedaAbreviada(valor) {
  const numero = Number(valor) || 0;
  const abs = Math.abs(numero);
  if (abs >= 1000000) {
    return (numero < 0 ? "-" : "") + "R$ " + (abs / 1000000).toFixed(1).replace(".", ",") + " mi";
  }
  if (abs >= 1000) {
    return (numero < 0 ? "-" : "") + "R$ " + Math.round(abs / 1000) + " mil";
  }
  return formatarMoeda(numero);
}

function formatarPercentual(valor) {
  if (valor === null || valor === undefined) return null;
  return valor.toFixed(1).replace(".", ",");
}

function escaparHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// Estilo do badge de % atingido: cinza abaixo de 70%, oliva claro de 70% a 99%, oliva forte com a meta batida.
function estiloPercentual(pct) {
  if (pct === null || pct < 70) return "neutro";
  if (pct < 100) return "medio";
  return "forte";
}

function semanaEMesLabel(dataIso) {
  const d = dataIso ? new Date(dataIso) : new Date();
  const dCopy = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const diaSemana = dCopy.getUTCDay() || 7;
  dCopy.setUTCDate(dCopy.getUTCDate() + 4 - diaSemana);
  const inicioAno = new Date(Date.UTC(dCopy.getUTCFullYear(), 0, 1));
  const semana = Math.ceil((((dCopy - inicioAno) / 86400000) + 1) / 7);
  const MESES = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
  return "Semana " + semana + " &middot; " + MESES[d.getUTCMonth()] + "/" + d.getUTCFullYear();
}

// Roda uma única vez, alimentado pela saída "concluído" do loop "Cada Vendedor" —
// só monta o HTML final e passa pro node de envio. Toda a inteligência de dados
// (agrupar, calcular comissão, etc.) já foi feita antes, em "Processar Carteiras".
// Layout inspirado no modelo de referência relatorio-meta-email-v2.html.
const r = $node["Processar Carteiras"].json.relatorio_gestor;
const geradoEm = $node["Processar Carteiras"].json.gerado_em;
const linhas = r.linhas_resumo || [];

// -------- Pódio (top 3 por faturamento) --------
const porFaturamentoDesc = linhas.slice().sort(function (a, b) { return b.faturamentoAtual - a.faturamentoAtual; });
const podio = porFaturamentoDesc.slice(0, 3);
const RANK_LABEL = ["1º", "2º", "3º"];
const linhasPodio = podio.map(function (p, i) {
  return [
    wpBadge(RANK_LABEL[i], i === 0 ? "forte" : "medio"),
    "<b>" + wpEsc(p.nome) + "</b>",
    "<b>" + formatarMoeda(p.faturamentoAtual) + "</b>",
    p.percentual === null ? "sem meta" : formatarPercentual(p.percentual) + "% da meta"
  ];
});

// -------- Faturamento por vendedor (top 8, barras relativas ao líder) --------
const top8 = porFaturamentoDesc.slice(0, 8);
const maiorFaturamento = top8.length > 0 ? top8[0].faturamentoAtual : 0;
const linhasBarras = top8.map(function (l, i) {
  const largura = maiorFaturamento > 0 ? Math.max(1, Math.round((l.faturamentoAtual / maiorFaturamento) * 100)) : 0;
  return ["<b>" + wpEsc(l.nome) + "</b>" + wpBarra(largura, i === 0), "<b>" + formatarMoeda(l.faturamentoAtual) + "</b>"];
});

// -------- Detalhamento completo (ordenado por % crescente, como já era) --------
const linhasDetalhe = linhas.map(function (l) {
  const percLabel = l.percentual === null ? "sem meta" : formatarPercentual(l.percentual) + "%";
  return [
    "<b>" + wpEsc(l.nome) + "</b>",
    formatarMoeda(l.faturamentoAtual),
    wpBadge(percLabel, estiloPercentual(l.percentual), "right"),
    String(l.qtdAtendidos),
    String(l.qtdPendentes)
  ];
});

// -------- Nota de meta (só quando é igual pra todo mundo, senão fica genérica) --------
let metasDistintas = false;
let metaComumTexto = "";
for (let i = 0; i < linhas.length; i++) {
  if (linhas[i].meta > 0) {
    if (metaComumTexto === "") {
      metaComumTexto = formatarMoeda(linhas[i].meta);
    } else if (formatarMoeda(linhas[i].meta) !== metaComumTexto) {
      metasDistintas = true;
    }
  }
}
const notaMeta = metaComumTexto === "" ? "" :
  (metasDistintas
    ? "Metas individuais variam por vendedor."
    : "Meta individual de " + metaComumTexto + " para todos os vendedores.");

// -------- Hero: % global, barra, faltante --------
const pctGlobal = r.percentual_atingimento_global;
const pctGlobalLabel = pctGlobal === null ? "sem meta cadastrada" : formatarPercentual(pctGlobal) + "%";
const faltante = r.meta_total_empresa - r.faturamento_total_empresa;
const notaFaltante = r.meta_total_empresa <= 0
  ? ""
  : (faltante > 0
      ? "Faltam " + formatarMoeda(faltante) + " para bater a meta do mês"
      : "Meta da empresa batida neste mês! 🎉");

// -------- Pendências de cadastro (só aparece se houver algo a avisar) --------
const temPendencias = (r.vendedores_sem_email.length > 0) || (r.vendedores_sem_telefone.length > 0) || (r.grupos_sem_atividade_ocultos > 0) || (r.qtd_vendedores_fora_da_planilha > 0);
let blocoPendencias = "";
if (temPendencias) {
  // Lista nominal de quem ficou sem e-mail ou sem telefone válido, com o motivo.
  function listaPendentes(titulo, consequencia, lista) {
    if (lista.length === 0) return "";
    let html = '<span style="display:block;padding-top:10px;"><strong>' + titulo + ' (' + lista.length + ')</strong> ' + consequencia + '</span>';
    for (let i = 0; i < lista.length; i++) {
      const p = lista[i];
      html += '<span style="display:block;padding-left:10px;">&bull; ' + wpEsc(p.nome) + ' (código ' + wpEsc(p.codigo) + ') <span style="color:#6B7280;">' + wpEsc(p.motivo) + '</span></span>';
    }
    return html;
  }
  const corpoPendencias =
    listaPendentes("Sem e-mail válido", "não recebem o resumo por e-mail:", r.vendedores_sem_email) +
    listaPendentes("Sem telefone válido", "não recebem o resumo por WhatsApp:", r.vendedores_sem_telefone) +
    (r.grupos_sem_atividade_ocultos > 0 ? '<span style="display:block;padding-top:10px;">' + r.grupos_sem_atividade_ocultos + ' código(s) sem venda ou carteira no mês foram ocultados deste relatório.</span>' : '') +
    (r.qtd_vendedores_fora_da_planilha > 0 ? '<span style="display:block;padding-top:8px;">Você possui <strong>' + r.qtd_vendedores_fora_da_planilha + ' vendedor(es) sem meta cadastrada</strong> na planilha de metas.</span>' : '');
  blocoPendencias = wpAviso("Pendências de cadastro", corpoPendencias, "medio");
}

const miolo =
  wpKpis([
    { rotulo: "Faturamento", valor: formatarMoeda(r.faturamento_total_empresa) },
    { rotulo: "Meta da empresa", valor: r.meta_total_empresa > 0 ? formatarMoedaAbreviada(r.meta_total_empresa) : "-" }
  ]) +
  (podio.length > 0 ? wpSecao("Pódio da semana", "Os três maiores faturamentos do mês") +
    wpTabela([{ t: "#", w: "44" }, { t: "Vendedor" }, { t: "Faturamento", a: "right" }, { t: "Meta", a: "right", oculta: true }], linhasPodio) : "") +
  (top8.length > 0 ? wpSecao("Faturamento por vendedor", "Top " + top8.length + " por volume faturado") +
    wpTabela([{ t: "Vendedor" }, { t: "Faturamento", a: "right", w: "120" }], linhasBarras) : "") +
  wpSecao("Detalhamento completo", "Ordenado do menor para o maior % de atingimento") +
  wpTabela([{ t: "Vendedor" }, { t: "Faturamento", a: "right" }, { t: "% Atingido", a: "right" }, { t: "Atend.", a: "right", oculta: true }, { t: "Pend.", a: "right", oculta: true }], linhasDetalhe, notaMeta) +
  blocoPendencias;

const corpoEmailGestor = wpPagina({
  titulo: "Relatório consolidado da semana",
  preheader: pctGlobalLabel + " da meta mensal alcançados: " + formatarMoeda(r.faturamento_total_empresa) + " de " + (r.meta_total_empresa > 0 ? formatarMoeda(r.meta_total_empresa) : "sem meta cadastrada") + ".",
  empresa: CONFIG.nomeEmpresa,
  rotuloDireita: semanaEMesLabel(geradoEm),
  eyebrow: "Coach dos representantes",
  heroEyebrow: "Atingimento global",
  heroValor: pctGlobalLabel,
  heroSub: formatarMoeda(r.faturamento_total_empresa) + " de " + (r.meta_total_empresa > 0 ? formatarMoeda(r.meta_total_empresa) : "sem meta cadastrada"),
  heroBarra: pctGlobal === null ? null : pctGlobal,
  heroNota: notaFaltante,
  saudacao: "Bom dia, <strong>" + wpEsc(r.nome_gestor) + "</strong>!",
  subSaudacao: "Segue o relatório consolidado da semana para apoiar a reunião comercial.",
  miolo: miolo,
  rodape: ["Mensagem automática do sistema comercial " + wpEsc(CONFIG.nomeEmpresa) + ".", "Londrisoft &mdash; Londrina, PR"]
});

return [{
  json: {
    assunto: r.assunto,
    corpo_html: corpoEmailGestor
  }
}];

const CONFIG = {
  limiteClientesResumo: 10,
  nomeEmpresa: "NOME DA EMPRESA",
  // Rodapé do WhatsApp e do e-mail do vendedor: quem atende as dúvidas.
  contatoDuvidasNome: "Nome do Responsável",
  contatoDuvidasWhatsapp: "(00) 00000-0000",
  // Teto do motor de expressões do Waipe Flow: QUALQUER {{ }} que resolva acima
  // de 262.144 bytes falha o node com "ExpressionResultTooLarge" (documentado,
  // sem exceção pra google_docs.content nem gmail_send.body — só http_request
  // e webhook_respond têm teto maior). Já aconteceu: um grupo com milhares de
  // pendentes gerou 1.495.063 bytes de tabela e derrubou o node. Por isso as
  // tabelas completas (corpo_email_resumo e corpo_documento_pdf) são montadas
  // com um orçamento de bytes, não uma contagem fixa de linhas — corta o quanto
  // for preciso pra caber com folga, e avisa quantos clientes ficaram de fora.
  orcamentoBytesTabela: 180000
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + wpEsc(o.preheader || "") + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='wp-bg' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wp-wrap' style='width:600px;max-width:600px;'>";
  // Marca
  h += "<tr><td class='wp-pad' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='wp-t' style='" + WP_F + "font-size:22px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "<td align='right' class='wp-m' style='" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(o.empresa || "") + (o.rotuloDireita ? "<br>" + o.rotuloDireita : "") + "</td>";
  h += "</tr></table></td></tr>";
  // Cartão
  h += "<tr><td bgcolor='#FEFEFE' class='wp-card' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:12px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:12px 12px 0 0;'>&nbsp;</td></tr>";
  if (eyebrow || o.titulo || o.saudacao) {
    h += "<tr><td class='wp-pad' style='padding:32px 32px 8px 32px;'>";
    if (eyebrow) h += "<p class='wp-eb' style='margin:0 0 8px 0;" + WP_F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(eyebrow) + "</p>";
    if (o.titulo) h += "<h1 class='wp-h1 wp-t' style='margin:0 0 12px 0;" + WP_F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + wpEsc(o.titulo) + "</h1>";
    if (o.saudacao) h += "<p class='wp-t' style='margin:0;" + WP_F + "font-size:15px;color:#303030;mso-line-height-rule:exactly;line-height:23px;'>" + o.saudacao + "</p>";
    if (o.subSaudacao) h += "<p class='wp-m' style='margin:6px 0 0 0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + o.subSaudacao + "</p>";
    h += "</td></tr>";
  }
  if (o.heroValor !== undefined && o.heroValor !== null) {
    const tam = Math.min(o.heroTam || 44, 48);
    h += "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F1F2EC' style='background:#F1F2EC;border-radius:8px;padding:20px;'>";
    if (o.heroEyebrow && o.eyebrow && o.eyebrow !== o.heroEyebrow) h += "<p class='wp-c-medio' style='margin:0 0 6px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#5A6344;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(o.heroEyebrow) + "</p>";
    h += "<p class='wp-hero wp-c-medio' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:#5A6344;letter-spacing:-1px;mso-line-height-rule:exactly;line-height:" + (tam + 4) + "px;'>" + wpEsc(o.heroValor) + "</p>";
    if (o.heroSub) h += "<p class='wp-c-medio' style='margin:6px 0 0 0;" + WP_F + "font-size:14px;color:#5A6344;mso-line-height-rule:exactly;line-height:20px;'>" + o.heroSub + "</p>";
    if (o.heroBarra !== undefined && o.heroBarra !== null) {
      const w = Math.max(0, Math.min(100, Math.round(o.heroBarra)));
      h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:14px;'><tr><td bgcolor='#E3E6D8' style='background:#E3E6D8;border-radius:5px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" +
        "<td width='" + w + "%' height='10' bgcolor='#5A6344' style='height:10px;background:#5A6344;border-radius:5px;font-size:0;line-height:0;'>&nbsp;</td>" +
        (w < 100 ? "<td height='10' style='height:10px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table></td></tr></table>";
    }
    if (o.heroNota) h += "<p class='wp-c-medio' style='margin:10px 0 0 0;" + WP_F + "font-size:12px;color:#5A6344;mso-line-height-rule:exactly;line-height:18px;'>" + o.heroNota + "</p>";
    h += "</td></tr></table></td></tr>";
  }
  h += o.miolo || "";
  h += "<tr><td style='height:24px;font-size:0;line-height:0;'>&nbsp;</td></tr>";
  h += "</table></td></tr>";
  // Rodapé
  const linhasRodape = o.rodape || [];
  h += "<tr><td class='wp-pad' align='center' style='padding:24px 24px 0 24px;'>";
  for (let i = 0; i < linhasRodape.length; i++) {
    h += "<p class='wp-m' style='margin:" + (i > 0 ? "6px" : "0") + " 0 0 0;" + WP_F + "font-size:12px;color:" + (i === linhasRodape.length - 1 ? "#8A90A0" : "#6B7280") + ";mso-line-height-rule:exactly;line-height:18px;'>" + linhasRodape[i] + "</p>";
  }
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

// Parágrafo livre (HTML já escapado pelo chamador)
function wpTexto(html) {
  return "<tr><td class='wp-pad' style='padding:8px 32px;'><p class='wp-m' style='margin:0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + html + "</p></td></tr>";
}

// Título de seção com subtítulo
function wpSecao(titulo, sub) {
  return "<tr><td class='wp-pad' style='padding:24px 32px 12px 32px;'>" +
    "<p class='wp-t' style='margin:0;" + WP_F + "font-size:16px;font-weight:bold;color:#303030;mso-line-height-rule:exactly;line-height:22px;'>" + wpEsc(titulo) + "</p>" +
    (sub ? "<p class='wp-m' style='margin:4px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:18px;'>" + sub + "</p>" : "") + "</td></tr>";
}

// Cartões de indicador lado a lado. lista: [{rotulo, valor, estilo, sub}], titulo (opcional) vira um rótulo pequeno acima.
// Sem estilo, o primeiro é "medio" (verde-oliva) e os outros "neutro", como no Guardião.
function wpKpis(lista, titulo) {
  const n = lista.length;
  const larg = (100 / n).toFixed(2);
  let h = "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'>";
  if (titulo) h += "<p class='wp-m' style='margin:0 0 8px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(titulo) + "</p>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  // Valor longo (ex.: R$ 99.716,16) com 3 ou mais cartões lado a lado: fonte menor para caber numa linha.
  const maiorValor = lista.reduce(function (m, k) { return Math.max(m, String(k.valor === undefined ? "" : k.valor).length); }, 0);
  const tam = n >= 3 && maiorValor > 9 ? 20 : n >= 2 && maiorValor > 14 ? 20 : 26;
  for (let i = 0; i < n; i++) {
    const k = lista[i];
    const nome = WP_ESTILOS[k.estilo] ? k.estilo : (i === 0 ? "medio" : "neutro");
    const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
    const cls = nome === "forte" ? "medio" : nome;
    const pad = n === 1 ? "" : (i === 0 ? "padding-right:6px;" : (i === n - 1 ? "padding-left:6px;" : "padding:0 3px;"));
    h += "<td class='wp-kpi' width='" + larg + "%' valign='top' style='width:" + larg + "%;" + pad + "'>" +
      "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:8px;padding:16px;'>" +
      "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:" + (tam + 6) + "px;white-space:nowrap;'>" + wpEsc(k.valor) + "</p>" +
      "<p class='wp-c-" + cls + "' style='margin:4px 0 0 0;" + WP_F + "font-size:13px;color:" + (nome === "neutro" ? "#5B6170" : e.cor) + ";mso-line-height-rule:exactly;line-height:18px;'>" + wpEsc(k.rotulo) + "</p>" +
      (k.sub ? "<p class='wp-m' style='margin:2px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(k.sub) + "</p>" : "") +
      "</td></tr></table></td>";
  }
  return h + "</tr></table></td></tr>";
}

// Tabela. colunas: [{t, a: "left"|"right"|"center", w, oculta}], linhas: [[html da célula, ...], ...]
// oculta = some em tela pequena. nota (opcional): texto abaixo da tabela.
function wpTabela(colunas, linhas, nota) {
  let h = "<tr><td class='wp-pad' style='padding:4px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='wp-bd' style='border:1px solid #E5E7EB;border-radius:8px;border-collapse:separate;'><tr>";
  for (let c = 0; c < colunas.length; c++) {
    const col = colunas[c];
    const canto = c === 0 ? "border-radius:8px 0 0 0;" : (c === colunas.length - 1 ? "border-radius:0 8px 0 0;" : "");
    h += "<td bgcolor='#F9FAFB' align='" + (col.a || "left") + "'" + (col.w ? " width='" + col.w + "'" : "") + " class='wp-soft wp-m" + (col.oculta ? " wp-hide" : "") + "'" +
      " style='background:#F9FAFB;padding:10px 12px;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;" + canto + "'>" + wpEsc(col.t) + "</td>";
  }
  h += "</tr>";
  if (linhas.length === 0) {
    h += "<tr><td colspan='" + colunas.length + "' class='wp-bd wp-m' style='border-top:1px solid #F3F4F6;padding:14px 12px;" + WP_F + "font-size:13px;color:#6B7280;'>Nada para mostrar.</td></tr>";
  }
  for (let i = 0; i < linhas.length; i++) {
    h += "<tr>";
    for (let c = 0; c < colunas.length; c++) {
      const col = colunas[c];
      h += "<td" + (col.a ? " align='" + col.a + "'" : "") + " valign='middle' class='wp-bd wp-t" + (col.oculta ? " wp-hide" : "") + "'" +
        " style='border-top:1px solid #F3F4F6;padding:10px 12px;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:18px;'>" + (linhas[i][c] === undefined ? "" : linhas[i][c]) + "</td>";
    }
    h += "</tr>";
  }
  h += "</table>" + (nota ? "<p class='wp-m' style='margin:8px 2px 0 2px;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:17px;'>" + nota + "</p>" : "") + "</td></tr>";
  return h;
}

// Pílula de destaque (para dentro de uma célula). a: "left" | "right". Texto curto (até 3 caracteres) vira círculo,
// como a posição do ranking do Guardião.
function wpBadge(texto, estilo, a) {
  const nome = WP_ESTILOS[estilo] ? estilo : "neutro";
  const e = nome === "neutro" ? { bg: "#F3F4F6", cor: "#5B6170" } : WP_ESTILOS[nome];
  const t = String(texto === null || texto === undefined ? "" : texto);
  const alinhar = a === "right" ? " align='right'" : "";
  if (t.length <= 3) {
    return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td width='24' height='24' align='center' valign='middle' bgcolor='" + e.bg + "' style='width:24px;height:24px;background:" + e.bg + ";border-radius:12px;" + WP_F + "font-size:12px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:24px;'>" + wpEsc(t) + "</td></tr></table>";
  }
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:20px;padding:3px 10px;" + WP_F + "font-size:11px;font-weight:bold;color:" + e.cor + ";white-space:nowrap;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(t) + "</td></tr></table>";
}

// Barra proporcional (para dentro de uma célula). pct 0-100; forte = verde-oliva cheio, senão oliva claro
function wpBarra(pct, forte) {
  const w = Math.max(4, Math.min(100, Math.round(pct)));
  const cor = forte ? "#5A6344" : "#BFC4AC";
  return "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:6px;'><tr>" +
    "<td width='" + w + "%' height='6' bgcolor='" + cor + "' style='height:6px;background:" + cor + ";border-radius:3px;font-size:0;line-height:0;'>&nbsp;</td>" +
    (w < 100 ? "<td width='" + (100 - w) + "%' height='6' style='height:6px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table>";
}

// Botão quadrado com seta (para dentro de uma célula): abre a planilha ou lista da linha
function wpSeta(url, titulo) {
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0' align='right'><tr><td width='32' height='32' align='center' valign='middle' bgcolor='#303030' style='width:32px;height:32px;background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' title='" + wpEsc(titulo) + "' aria-label='" + wpEsc(titulo) + "' style='display:block;width:32px;" + WP_F + "font-size:18px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:32px;border-radius:8px;'>&rarr;</a></td></tr></table>";
}

// Botão de chamada (linha própria)
function wpBotao(url, rotulo) {
  return "<tr><td class='wp-pad' align='left' style='padding:16px 32px 8px 32px;'><table role='presentation' cellpadding='0' cellspacing='0' border='0'><tr><td align='center' bgcolor='#303030' style='background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' style='display:block;padding:12px 24px;" + WP_F + "font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:20px;border-radius:8px;'>" + wpEsc(rotulo) + "</a></td></tr></table></td></tr>";
}

// Caixa de aviso (linha própria): titulo + corpo em HTML
function wpAviso(titulo, corpoHtml, estilo) {
  const nome = WP_ESTILOS[estilo] ? estilo : "medio";
  const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
  const cls = nome === "forte" ? "medio" : nome;
  return "<tr><td class='wp-pad' style='padding:16px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border:1px solid " + e.borda + ";border-radius:8px;padding:16px 18px;'>" +
    "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(titulo) + "</p>" +
    "<p class='wp-t' style='margin:8px 0 0 0;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:20px;'>" + corpoHtml + "</p></td></tr></table></td></tr>";
}
// ============================================================
// FIM DO PADRÃO DE E-MAIL WAIPE
// ============================================================

// Monta as linhas de uma tabela de clientes respeitando um orçamento de bytes:
// para de adicionar linhas assim que a próxima estourar o orçamento, e devolve
// quantas entraram e quantas ficaram de fora (pra montar um aviso "+N clientes").
function montarTabelaComOrcamento(lista, orcamentoBytes, linhaFn) {
  const linhas = [];
  let usado = 0;
  let i = 0;
  for (; i < lista.length; i++) {
    const linhaHtml = linhaFn(lista[i], i);
    if (usado + linhaHtml.length > orcamentoBytes) break;
    linhas.push(linhaHtml);
    usado += linhaHtml.length;
  }
  return { texto: linhas.join(""), exibidos: i, ocultos: lista.length - i };
}

function formatarMoeda(valor) {
  const numero = Number(valor) || 0;
  const negativo = numero < 0;
  const fixo = Math.abs(numero).toFixed(2);
  const partes = fixo.split(".");
  let inteiro = partes[0];
  const centavos = partes[1];
  let comSeparador = "";
  let contador = 0;
  for (let i = inteiro.length - 1; i >= 0; i--) {
    comSeparador = inteiro.charAt(i) + comSeparador;
    contador++;
    if (contador % 3 === 0 && i !== 0) {
      comSeparador = "." + comSeparador;
    }
  }
  return (negativo ? "-R$ " : "R$ ") + comSeparador + "," + centavos;
}

function formatarPercentual(valor) {
  if (valor === null || valor === undefined) return null;
  return valor.toFixed(1).replace(".", ",");
}

function escaparHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// Barra de progresso em blocos unicode (10 segmentos) para a mensagem de WhatsApp.
function barraProgresso(pct) {
  if (pct === null || pct === undefined) return "";
  const limitado = Math.max(0, Math.min(100, pct));
  const preenchidos = Math.round(limitado / 10);
  let barra = "";
  for (let i = 0; i < 10; i++) barra += i < preenchidos ? "▰" : "▱";
  return barra;
}

// Emoji de urgência por dias sem comprar (999999 = nunca comprou, cai no >=90).
function emojiUrgencia(dias) {
  if (dias >= 90) return "🔴";
  if (dias >= 30) return "🟡";
  return "🟢";
}

// Roda uma vez por vendedor, ANTES do switch de canal — monta tudo que os dois
// canais (WhatsApp e e-mail) vão precisar, pra que o documento/PDF seja gerado
// uma única vez e reaproveitado nos dois: mensagem resumida de WhatsApp, resumo
// em HTML pro corpo do e-mail (mesmos N mais urgentes) e o documento completo
// (todos os clientes pendentes, sem corte) que vira o PDF anexado no WhatsApp e
// vai embutido também no corpo do e-mail (gmail_send não tem campo de anexo —
// ver node "Enviar E-mail ao Vendedor").
//
// Modo "cada item" do node de código: a variável de item é $json direto
// (confirmado no guia oficial de nodes do Waipe Flow — cada execução recebe
// $json = o json do item atual, sem wrapper).
const v = $json;

const pendentes = v.clientes_pendentes || [];

// ---------- mensagem_whatsapp (resumida, só os N mais urgentes) ----------
const pendentesResumidos = pendentes.slice(0, CONFIG.limiteClientesResumo);
const qtdOcultosWhatsapp = pendentes.length - pendentesResumidos.length;

let textoPendentesWhatsapp = "";
for (let i = 0; i < pendentesResumidos.length; i++) {
  const l = pendentesResumidos[i];
  const detalhe = l.diasOrdenacao >= 999999
    ? "nunca comprou"
    : "última compra " + l.dataUltimaCompra + " · " + l.diasSemComprar + " dias sem comprar";
  textoPendentesWhatsapp += emojiUrgencia(l.diasOrdenacao) + " " + (i + 1) + ". " + l.nome + "\n" +
    "cód. " + l.codigo + " · " + detalhe + "\n";
}

const percentualLabelPonto = v.percentual_atingimento === null ? "sem meta cadastrada" : v.percentual_atingimento.toFixed(1) + "%";
const DIVISOR = "━━━━━━━━━━━━━━";
const RODAPE_LINHA1 = "Esta é uma mensagem automática do sistema comercial " + CONFIG.nomeEmpresa + ". Não é preciso respondê-la.";
const RODAPE_LINHA2 = "Se tiver alguma dúvida, fale com o " + CONFIG.contatoDuvidasNome + " pelo WhatsApp " + CONFIG.contatoDuvidasWhatsapp + ".";

let mensagemWhatsapp =
  "Olá, " + v.nome + "! Tenha um ótimo dia.\n" +
  "Estamos começando mais uma semana, graças a Deus. Deus abençoe nossa semana!\n" +
  "Aqui está o seu resumo de performance atualizado:\n" +
  DIVISOR + "\n" +
  "💰 Faturamento Atual no Mês\n" + formatarMoeda(v.faturamento_atual) + "\n" +
  "🎯 Meta do Mês\n" + (v.meta > 0 ? formatarMoeda(v.meta) : "sem meta cadastrada") + "\n" +
  "📈 % de Atingimento da Meta\n" + (v.percentual_atingimento === null ? "sem meta cadastrada" : barraProgresso(v.percentual_atingimento) + " " + percentualLabelPonto) + "\n";

if (v.comissao_cadastrada) {
  mensagemWhatsapp += "💵 Comissão Estimada do Mês\n" + formatarMoeda(v.comissao_valor) + (v.comissao_percentual !== null ? " (" + v.comissao_percentual.toFixed(1) + "% sobre o faturamento)" : "") + "\n";
}

mensagemWhatsapp += DIVISOR + "\n" +
  "✅ Clientes Atendidos no Mês: " + v.qtd_atendidos + "\n" +
  "⏳ Clientes Pendentes (Sem Compra): " + v.qtd_pendentes + "\n" +
  "🔔 Clientes da sua carteira sem comprar\n" +
  "(os mais urgentes primeiro)\n";
mensagemWhatsapp += textoPendentesWhatsapp === "" ? "🎉 Nenhum cliente pendente encontrado. Parabéns!\n" : textoPendentesWhatsapp;
if (qtdOcultosWhatsapp > 0) {
  mensagemWhatsapp += "➕ ...e mais " + qtdOcultosWhatsapp + " cliente(s) pendente(s) não exibido(s) aqui — lista completa no PDF em anexo.\n";
}
mensagemWhatsapp += DIVISOR + "\n" +
  "_" + RODAPE_LINHA1 + "_\n" +
  "_" + RODAPE_LINHA2 + "_";

// ---------- corpo_email_resumo (padrão de e-mail Waipe, com TODOS os clientes pendentes,
// sem corte de 10; só a mensagem de WhatsApp é resumida). As linhas entram até o orçamento
// de bytes (cada célula do kit tem ~260 bytes de estilo além do conteúdo).
const linhasResumoEmail = [];
let bytesTabela = 0;
for (let i = 0; i < pendentes.length; i++) {
  const l = pendentes[i];
  const detalhe = l.diasOrdenacao >= 999999 ? "Nunca comprou" : "Última compra " + l.dataUltimaCompra + " (" + l.diasSemComprar + " dias)";
  const linha = [wpEsc(l.codigo), "<b>" + wpEsc(l.nome) + "</b>", '<span style="color:#6B7280;">' + wpEsc(detalhe) + "</span>"];
  const tamanho = linha.join("").length + 780;
  if (bytesTabela + tamanho > CONFIG.orcamentoBytesTabela) break;
  linhasResumoEmail.push(linha);
  bytesTabela += tamanho;
}
const ocultosEmail = pendentes.length - linhasResumoEmail.length;

const pctIndividual = v.percentual_atingimento;
const pctIndividualLabel = pctIndividual === null ? "sem meta cadastrada" : formatarPercentual(pctIndividual) + "%";
const kpisVendedor = [
  { rotulo: "Faturamento", valor: formatarMoeda(v.faturamento_atual) },
  { rotulo: "Meta do mês", valor: v.meta > 0 ? formatarMoeda(v.meta) : "-" }
];
if (v.comissao_cadastrada) kpisVendedor.push({ rotulo: "Comissão", valor: formatarMoeda(v.comissao_valor) });

const corpoEmailResumo = wpPagina({
  titulo: "Seu resumo de performance",
  preheader: pctIndividualLabel + " da meta: " + formatarMoeda(v.faturamento_atual) + ". Veja os clientes da sua carteira sem comprar.",
  empresa: CONFIG.nomeEmpresa,
  rotuloDireita: "Coach dos representantes",
  eyebrow: "Coach dos representantes",
  heroEyebrow: "Seu atingimento de meta",
  heroValor: pctIndividualLabel,
  heroSub: formatarMoeda(v.faturamento_atual) + " de " + (v.meta > 0 ? formatarMoeda(v.meta) : "sem meta cadastrada"),
  heroBarra: pctIndividual === null ? null : pctIndividual,
  saudacao: "Olá, <strong>" + wpEsc(v.nome) + "</strong>!",
  subSaudacao: "Segue seu resumo de performance da semana.",
  miolo: wpKpis(kpisVendedor) +
    wpSecao("Clientes sem comprar", "Lista completa da sua carteira: " + v.qtd_pendentes + " cliente(s)") +
    (linhasResumoEmail.length > 0
      ? wpTabela([{ t: "Código", w: "70" }, { t: "Cliente" }, { t: "Situação" }], linhasResumoEmail,
        ocultosEmail > 0 ? "+" + ocultosEmail + " cliente(s) adicionais não exibidos aqui (lista muito extensa para caber no e-mail)." : "")
      : wpTabela([{ t: "Situação" }], [["&#10003; Nenhum cliente pendente. Parabéns!"]])),
  rodape: [wpEsc(RODAPE_LINHA1), wpEsc(RODAPE_LINHA2), "Londrisoft &mdash; Londrina, PR"]
});

// ---------- corpo_documento_pdf (documento claro — vira o PDF anexado) ----------
// Layout de DOCUMENTO de verdade (fundo branco), não um card de e-mail: a margem
// da página no PDF é controlada pelo Google Docs, não pela nossa CSS — então um
// conteúdo de fundo escuro sempre deixa uma borda branca ao redor no PDF. Fundo
// claro elimina esse problema na raiz, sem precisar (nem dar pra) zerar margem.
// Tabela montada com orçamento de bytes (mesma função usada no resumo do
// e-mail) — grupos catch-all (Televendas, B2C etc.) podem ter milhares de
// clientes pendentes, e um único {{ }} acima de 256 KB derruba o node
// google_docs com ExpressionResultTooLarge.
const tabelaDocumento = montarTabelaComOrcamento(pendentes, CONFIG.orcamentoBytesTabela, function (l, i) {
  const bg = i % 2 === 0 ? "#ffffff" : "#f2f3f8";
  const detalhe = l.diasOrdenacao >= 999999 ? "Nunca comprou" : "Última compra " + l.dataUltimaCompra + " (" + l.diasSemComprar + " dias)";
  return (
    '<tr>' +
    '<td style="padding:8px 10px;border-bottom:1px solid #ddd;background-color:' + bg + ';font-size:12px;color:#222222;">' + escaparHtml(l.codigo) + '</td>' +
    '<td style="padding:8px 10px;border-bottom:1px solid #ddd;background-color:' + bg + ';font-size:12px;color:#222222;">' + escaparHtml(l.nome) + '</td>' +
    '<td style="padding:8px 10px;border-bottom:1px solid #ddd;background-color:' + bg + ';font-size:12px;color:#555555;">' + escaparHtml(detalhe) + '</td>' +
    '</tr>'
  );
});
const linhasTabelaTexto = tabelaDocumento.texto;

const percentualLabelDoc = v.percentual_atingimento === null ? "sem meta cadastrada" : formatarPercentual(v.percentual_atingimento) + "%";

const corpoDocumentoPdf =
  '<div style="font-family:Arial,Helvetica,sans-serif;color:#222222;">' +
    '<div style="font-size:22px;font-weight:bold;color:#262a60;">' + CONFIG.nomeEmpresa + '</div>' +
    '<div style="font-size:13px;color:#666666;margin-top:2px;margin-bottom:22px;">Relatório Individual de Performance &mdash; ' + escaparHtml(v.nome) + '</div>' +

    '<table style="width:100%;border-collapse:collapse;margin-bottom:26px;">' +
      '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">Faturamento Atual no Mês</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + formatarMoeda(v.faturamento_atual) + '</td></tr>' +
      '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">Meta do Mês</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + (v.meta > 0 ? formatarMoeda(v.meta) : "sem meta cadastrada") + '</td></tr>' +
      '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">% de Atingimento da Meta</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + percentualLabelDoc + '</td></tr>' +
      '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">Clientes Atendidos no Mês</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + v.qtd_atendidos + '</td></tr>' +
      '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">Clientes Pendentes (Sem Compra)</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + v.qtd_pendentes + '</td></tr>' +
      (v.comissao_cadastrada ? '<tr><td style="padding:5px 0;font-size:13px;color:#555555;">Comissão Estimada do Mês</td><td style="padding:5px 0;font-size:13px;text-align:right;font-weight:bold;color:#222222;">' + formatarMoeda(v.comissao_valor) + '</td></tr>' : '') +
    '</table>' +

    '<div style="font-size:16px;font-weight:bold;color:#262a60;border-bottom:2px solid #262a60;padding-bottom:6px;margin-bottom:10px;">Clientes sem comprar (' + v.qtd_pendentes + ')</div>' +
    '<table style="width:100%;border-collapse:collapse;">' +
      '<tr style="background-color:#262a60;">' +
        '<th style="padding:8px 10px;text-align:left;font-size:11px;color:#ffffff;">Código</th>' +
        '<th style="padding:8px 10px;text-align:left;font-size:11px;color:#ffffff;">Cliente</th>' +
        '<th style="padding:8px 10px;text-align:left;font-size:11px;color:#ffffff;">Situação</th>' +
      '</tr>' +
      (linhasTabelaTexto || '<tr><td colspan="3" style="padding:10px;font-size:12px;color:#555555;">Nenhum cliente pendente. Parabéns!</td></tr>') +
    '</table>' +
    (tabelaDocumento.ocultos > 0 ? '<div style="font-size:11px;color:#999999;margin-top:8px;">+' + tabelaDocumento.ocultos + ' cliente(s) adicionais não exibidos aqui (lista muito extensa para caber no documento).</div>' : '') +

    '<div style="font-size:11px;color:#999999;margin-top:26px;">Mensagem automática do sistema comercial ' + CONFIG.nomeEmpresa + '.</div>' +
  '</div>';

return {
  json: Object.assign({}, v, {
    mensagem_whatsapp: mensagemWhatsapp,
    corpo_email_resumo: corpoEmailResumo,
    corpo_documento_pdf: corpoDocumentoPdf
  })
};
